  .igi-lb__btn{position:absolute;background:rgba(255,255,255,.10);color:#fff;border:none;cursor:pointer;width:48px;height:48px;border-radius:999px;font-size:24px;line-height:1;display:flex;align-items:center;justify-content:center;transition:background .15s;}
  .igi-lb__btn:hover{background:rgba(255,255,255,.24);}
  .igi-lb__close{top:20px;right:20px;font-size:26px;}
  .igi-lb__prev{left:18px;top:50%;transform:translateY(-50%);}
  .igi-lb__next{right:18px;top:50%;transform:translateY(-50%);}
  .igi-lb__count{position:absolute;bottom:22px;left:0;right:0;text-align:center;color:rgba(255,255,255,.85);font-family:"Spline Sans Mono",monospace;font-size:13px;letter-spacing:.06em;}
  @media (max-width:600px){.igi-lb__prev{left:6px}.igi-lb__next{right:6px}.igi-lb__btn{width:42px;height:42px}}

  .igi-port .igi-story{margin-top:clamp(30px,4vw,48px);}
  .igi-port .igi-story__head{display:flex;align-items:baseline;justify-content:space-between;gap:12px;flex-wrap:wrap;margin-bottom:18px;}
  .igi-port .igi-story__label{font-family:"Spline Sans Mono",monospace;font-size:11.5px;letter-spacing:.08em;text-transform:uppercase;}
  .igi-port .igi-story__hint{font-family:"Spline Sans Mono",monospace;font-size:10.5px;letter-spacing:.06em;text-transform:uppercase;opacity:.75;}
  .igi-port .igi-story__track{display:grid;grid-template-columns:repeat(auto-fit,minmax(min(100%,190px),1fr));gap:clamp(12px,1.6vw,18px);}
  .igi-port .igi-story__step{display:flex;flex-direction:column;height:auto;overflow:visible;border-radius:0;cursor:pointer;}
  .igi-port .igi-story__media{position:relative;display:block;aspect-ratio:4/3;overflow:hidden;border-radius:10px;}
  .igi-port .igi-story__media img{width:100%;height:100%;object-fit:cover;display:block;transition:transform .35s ease;}
  .igi-port .igi-story__step:hover .igi-story__media img{transform:scale(1.05);}
  .igi-port .igi-story__cap{display:block;padding-top:11px;}
  .igi-port .igi-story__stage{display:block;font-family:"Spline Sans Mono",monospace;font-size:11px;letter-spacing:.05em;text-transform:uppercase;margin-bottom:5px;}
  .igi-port .igi-story__text{display:block;font-size:13.5px;line-height:1.45;}
  </style>
  <div class="igi-lb" id="igi-lb" role="dialog" aria-modal="true" aria-label="Project gallery" hidden>
    <button class="igi-lb__btn igi-lb__close" type="button" aria-label="Close gallery">&times;</button>
    <button class="igi-lb__btn igi-lb__prev" type="button" aria-label="Previous photo">&#8249;</button>
    <img class="igi-lb__img" src="" alt="">
    <button class="igi-lb__btn igi-lb__next" type="button" aria-label="Next photo">&#8250;</button>
    <div class="igi-lb__count"></div>
  </div>
  <script>
  (function(){
    var lb=document.getElementById('igi-lb'); if(!lb) return;
    var img=lb.querySelector('.igi-lb__img'), count=lb.querySelector('.igi-lb__count');
    var list=[], idx=0;
    function show(){var it=list[idx]; if(!it)return; img.src=it.full; img.alt=it.alt||''; count.textContent=(idx+1)+' / '+list.length;}
    function open(items,start){list=items; idx=start||0; lb.hidden=false; lb.classList.add('is-open'); document.documentElement.style.overflow='hidden'; show();}
    function close(){lb.classList.remove('is-open'); lb.hidden=true; document.documentElement.style.overflow=''; img.src='';}
    function go(d){if(!list.length)return; idx=(idx+d+list.length)%list.length; show();}
    document.addEventListener('click',function(e){
      var item=e.target.closest && e.target.closest('.igi-gal__item');
      if(item){var gal=item.closest('[data-igi-gal]'); if(!gal)return; e.preventDefault();
        var anchors=[].slice.call(gal.querySelectorAll('.igi-gal__item'));
        var items=anchors.map(function(a){var im=a.querySelector('img'); return {full:a.getAttribute('data-full')||a.getAttribute('href'), alt:im?im.alt:''};});
        open(items, anchors.indexOf(item)); return;}
      if(lb.hidden) return;
      if((e.target.closest && e.target.closest('.igi-lb__close')) || e.target===lb){close(); return;}
      if(e.target.closest && e.target.closest('.igi-lb__next')){go(1); return;}
      if(e.target.closest && e.target.closest('.igi-lb__prev')){go(-1); return;}
    });
    document.addEventListener('keydown',function(e){ if(lb.hidden)return;
      if(e.key==='Escape')close(); else if(e.key==='ArrowRight')go(1); else if(e.key==='ArrowLeft')go(-1);});
  })();
  </script>
  </div></div>
<!-- /wp:html -->
</div>
